import{_ as t,o as e,c as o,ah as a}from"./chunks/framework.Yx0DUrwu.js";const C=JSON.parse('{"title":"适应性免疫应答","description":"","frontmatter":{},"headers":[],"relativePath":"biology/adaptive-effector-immunity.md","filePath":"biology/adaptive-effector-immunity.md","lastUpdated":1787830595000}'),c={name:"biology/adaptive-effector-immunity.md"};function r(i,d,h,n,l,s){return e(),o("div",null,[...d[0]||(d[0]=[a('<h1 id="适应性免疫应答" tabindex="-1">适应性免疫应答 <a class="header-anchor" href="#适应性免疫应答" aria-label="Permalink to &quot;适应性免疫应答&quot;">​</a></h1><p>适应性免疫应答的主线是：抗原在次级淋巴器官中被呈递给初始淋巴细胞，特异性克隆扩增并分化为效应细胞，随后一部分细胞死亡以结束反应，另一部分成为记忆细胞。T 细胞和 B 细胞应答相互配合，形成针对不同病原体和组织环境的效应模块 [1]。</p><h2 id="t-细胞启动" tabindex="-1">T 细胞启动 <a class="header-anchor" href="#t-细胞启动" aria-label="Permalink to &quot;T 细胞启动&quot;">​</a></h2><div class="flow-strip"><span>APC 摄取抗原</span><span>APC 成熟迁移</span><span>淋巴结内相遇</span><span>TCR 识别肽-MHC</span><span>共刺激</span><span>细胞因子极化</span><span>克隆扩增</span><span>效应/记忆分化</span></div><p>T 细胞活化通常需要三类信息：TCR 特异性、共刺激和细胞因子环境。单细胞数据中如果只看到 <code>CD3D</code>、<code>CD4</code> 或 <code>CD8A</code>，只能说明谱系；判断功能状态还要看细胞因子、转录因子、细胞毒性基因、免疫检查点受体和克隆扩增。</p><h2 id="cd4-t-细胞效应模块" tabindex="-1">CD4 T 细胞效应模块 <a class="header-anchor" href="#cd4-t-细胞效应模块" aria-label="Permalink to &quot;CD4 T 细胞效应模块&quot;">​</a></h2><table tabindex="0"><thead><tr><th>亚群</th><th>关键因子</th><th>典型功能</th><th>常见标志基因</th></tr></thead><tbody><tr><td>Th1</td><td>IL-12、IFN-gamma、T-bet</td><td>激活巨噬细胞，对付胞内病原。</td><td><code>TBX21</code>, <code>IFNG</code>, <code>CXCR3</code></td></tr><tr><td>Th2</td><td>IL-4, GATA3</td><td>驱虫、过敏、屏障修复。</td><td><code>GATA3</code>, <code>IL4</code>, <code>IL5</code>, <code>IL13</code></td></tr><tr><td>Th17</td><td>IL-6, IL-23, TGF-beta, RORC</td><td>对付胞外菌和真菌，驱动屏障炎症。</td><td><code>RORC</code>, <code>IL17A</code>, <code>IL17F</code>, <code>CCR6</code></td></tr><tr><td>Tfh</td><td>BCL6、ICOS、CXCR5</td><td>帮助 B 细胞生发中心反应、类别转换和亲和力成熟。</td><td><code>CXCR5</code>, <code>ICOS</code>, <code>BCL6</code>, <code>IL21</code></td></tr><tr><td>Treg</td><td>FOXP3, IL2RA, CTLA4</td><td>抑制过强或自身反应性免疫。</td><td><code>FOXP3</code>, <code>IL2RA</code>, <code>CTLA4</code>, <code>IKZF2</code></td></tr></tbody></table><h2 id="cd8-t-细胞和细胞毒性" tabindex="-1">CD8 T 细胞和细胞毒性 <a class="header-anchor" href="#cd8-t-细胞和细胞毒性" aria-label="Permalink to &quot;CD8 T 细胞和细胞毒性&quot;">​</a></h2><p>CD8 细胞毒性 T 细胞通过穿孔素/颗粒酶通路或死亡受体通路杀伤靶细胞。单细胞中常见细胞毒性程序包括 <code>NKG7</code>, <code>PRF1</code>, <code>GZMB</code>, <code>GZMH</code>, <code>GNLY</code>。但细胞毒性基因同时可见于 NK 细胞，所以注释时要结合 TCR/CD3 基因与 NK 受体基因。</p><div class="doc-callout warning"><strong>耗竭需要组合证据</strong><p>`PDCD1`、`LAG3`、`TIGIT`、`HAVCR2`、`TOX` 等可以提示耗竭样状态，但感染、肿瘤、近期激活和组织驻留都会改变这些基因。最好结合克隆型、效应基因、样本来源和功能证据。</p></div><h2 id="b-细胞、抗体和生发中心" tabindex="-1">B 细胞、抗体和生发中心 <a class="header-anchor" href="#b-细胞、抗体和生发中心" aria-label="Permalink to &quot;B 细胞、抗体和生发中心&quot;">​</a></h2><p>B 细胞活化可以依赖 T 细胞，也可以不依赖 T 细胞。在 T 细胞依赖性应答中，B 细胞捕获抗原后向 Tfh 提呈，得到 CD40 和细胞因子辅助，进入生发中心，经历体细胞高频突变、亲和力成熟和类别转换重组。</p><table tabindex="0"><thead><tr><th>阶段</th><th>关键事件</th><th>单细胞线索</th></tr></thead><tbody><tr><td>活化</td><td>抗原结合、T-B 连锁识别</td><td><code>CD69</code>, <code>CD83</code>, <code>HLA-DRA</code>, <code>CD40</code></td></tr><tr><td>生发中心反应</td><td>增殖、突变、选择</td><td><code>BCL6</code>, <code>AICDA</code>, <code>MKI67</code></td></tr><tr><td>类别转换</td><td>IgM/IgD 转向 IgG/IgA/IgE</td><td><code>IGHG*</code>, <code>IGHA*</code>, <code>IGHE</code></td></tr><tr><td>浆细胞分化</td><td>抗体分泌</td><td><code>XBP1</code>, <code>MZB1</code>, <code>JCHAIN</code>, <code>SDC1</code></td></tr><tr><td>记忆形成</td><td>快速二次应答</td><td><code>CD27</code>, 已转换的抗体同种型</td></tr></tbody></table><h2 id="免疫记忆" tabindex="-1">免疫记忆 <a class="header-anchor" href="#免疫记忆" aria-label="Permalink to &quot;免疫记忆&quot;">​</a></h2><p>记忆 B 细胞通常比初始 B 细胞更快启动，并可在二次应答中继续亲和力成熟。记忆 T 细胞可粗略分为中央记忆、效应记忆和组织驻留记忆。单细胞里不要只按 <code>CCR7</code> 或 <code>IL7R</code> 单基因判断；最好结合归巢受体、效应基因、组织驻留基因和样本组织来源。</p><h2 id="自检问题" tabindex="-1">自检问题 <a class="header-anchor" href="#自检问题" aria-label="Permalink to &quot;自检问题&quot;">​</a></h2><ol><li>T 细胞启动为什么需要抗原提呈细胞成熟和共刺激？</li><li>Th1、Th2、Th17 分别适合应对哪类威胁？</li><li>Tfh 如何影响 B 细胞类别转换和亲和力成熟？</li><li>CD8 T 细胞和 NK 细胞的细胞毒性基因程序如何区分？</li></ol><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p>[1] Murphy, K. &amp; Weaver, C. <em>Janeway&#39;s Immunobiology</em>. 9th ed. Garland Science (2017). 中文版：《詹韦免疫生物学：原书第九版》，科学出版社，2022。</p>',19)])])}const T=t(c,[["render",r]]);export{C as __pageData,T as default};
